import React, { useState } from "react";
import HoneyComb from "../Assets/honeycomb.png";
import HoneyAmla from "../Assets/honeyamla.png";
import HoneyGarlic from "../Assets/honeygarlic.png";
import OriginalHoney from "../Assets/originalhoney.jpeg";

const products = [
  {
    id: 1,
    name_en: "Pure Forest Honey",
    name_ta: "தூய காட்டு தேன்",
    price: "₹450",
    image: OriginalHoney,
  },
  {
    id: 2,
    name_en: "Honey Comb",
    name_ta: "தேன்",
    price: "₹380",
    image: HoneyComb,
  },
  {
    id: 3,
    name_en: "Honey with Amla",
    name_ta: "தேன் நெல்லிக்காய்",
    price: "₹520",
    image: HoneyAmla,
  },
  {
    id: 4,
    name_en: "Honey with Garlic",
    name_ta: "தேன் பூண்டு",
    price: "₹520",
    image: HoneyGarlic,
  },
];

function Home() {
  const [language, setLanguage] = useState("en");

  return (
    <div>

      {/* Navbar */}
      <nav
        className="navbar navbar-expand-lg px-4"
        style={{ backgroundColor: "#4e342e" }}
      >
        <a className="navbar-brand fw-bold text-white" href="#">
          O.I.HONEY WORLD
        </a>

        <div className="ms-auto">
          <a className="nav-link d-inline text-white me-3" href="#products">
            {language === "en" ? "Products" : "பொருட்கள்"}
          </a>
          <a className="nav-link d-inline text-white" href="#contact">
            {language === "en" ? "Contact" : "தொடர்பு"}
          </a>
        </div>
      </nav>

      {/* Language Toggle */}
      <div className="text-end px-4 py-2" style={{ backgroundColor: "#fff8e1" }}>
        <button
          className="btn btn-sm me-2"
          style={{
            backgroundColor: language === "en" ? "#d4a017" : "white",
            color: language === "en" ? "white" : "#4e342e",
            border: "1px solid #d4a017",
          }}
          onClick={() => setLanguage("en")}
        >
          English
        </button>

        <button
          className="btn btn-sm"
          style={{
            backgroundColor: language === "ta" ? "#d4a017" : "white",
            color: language === "ta" ? "white" : "#4e342e",
            border: "1px solid #d4a017",
          }}
          onClick={() => setLanguage("ta")}
        >
          தமிழ்
        </button>
      </div>

      {/* Hero Section */}
      <section
        className="text-center py-5"
        style={{
          background: "linear-gradient(135deg, #f4b400, #fff8e1)",
        }}
      >
        <h1 className="fw-bold mb-3" style={{ color: "#4e342e" }}>
          {language === "en"
            ? "100% Natural & Pure Honey 🍯"
            : "100% இயற்கை மற்றும் தூய தேன் 🍯"}
        </h1>

        <p className="lead">
          {language === "en"
            ? "Fresh from the farm. No additives. No chemicals."
            : "பண்ணையிலிருந்து நேரடியாக. சேர்க்கைகள் இல்லை. ரசாயனங்கள் இல்லை."}
        </p>

        <button
          className="btn mt-3"
          style={{
            backgroundColor: "#4e342e",
            color: "white",
            padding: "10px 25px",
            borderRadius: "30px",
          }}
        >
          {language === "en" ? "Shop Now" : "இப்போது வாங்குங்கள்"}
        </button>
      </section>

      {/* Products */}
      <section id="products" className="container py-5">
        <h2
          className="text-center mb-5 fw-bold"
          style={{ color: "#4e342e" }}
        >
          {language === "en" ? "Our Products" : "எங்கள் பொருட்கள்"}
        </h2>

        <div className="row">
          {products.map((product) => (
            <div key={product.id} className="col-md-3 mb-4">
              <div
                className="card border-0 shadow-lg h-100"
                style={{
                  borderRadius: "15px",
                  transition: "transform 0.3s",
                }}
              >
                <img
                  src={product.image}
                  alt={product.name_en}
                  className="card-img-top"
                  style={{
                    height: "220px",
                    objectFit: "cover",
                    borderTopLeftRadius: "15px",
                    borderTopRightRadius: "15px",
                  }}
                />

                <div className="card-body text-center">
                  <h5 className="fw-bold">
                    {language === "en"
                      ? product.name_en
                      : product.name_ta}
                  </h5>

                  <p style={{ color: "#d4a017", fontWeight: "bold" }}>
                    {product.price}
                  </p>

                  <button
                    className="btn"
                    style={{
                      backgroundColor: "#d4a017",
                      color: "white",
                      borderRadius: "20px",
                      padding: "6px 20px",
                    }}
                  >
                    {language === "en"
                      ? "Buy Now"
                      : "இப்போது வாங்க"}
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Contact */}
      <section
        id="contact"
        className="text-center py-5"
        style={{ backgroundColor: "#4e342e", color: "white" }}
      >
        <h2 className="fw-bold">
          {language === "en" ? "Contact Us" : "தொடர்பு கொள்ள"}
        </h2>

        <p>📞 +91 9715123277</p>
        <p>
          📍 1/14, Sivankudiyetru, Padukapathu, Thoothukudi,
          Tamil Nadu - 628703
        </p>
      </section>

      {/* Footer */}
      <footer
        className="text-center py-3"
        style={{ backgroundColor: "#d4a017", color: "white" }}
      >
        <strong>© 2026 O.I.HONEY WORLD</strong>
      </footer>
    </div>
  );
}

export default Home;
